const hp = (d, fill, sw) => `<path d="${d}" fill="${fill}" stroke="${SK}" stroke-width="${sw||2}" stroke-linejoin="round"/>`;
const brim = (y, w, fill) => hp(`M${60-w},${y} Q60,${y-8} ${60+w},${y} Q${60+w-2},${y+6} 60,${y+3} Q${60-w+2},${y+6} ${60-w},${y}Z`, fill);
function flowerCrown(leaf, cols, big){
  let s = ""; const n = 12;
  for (let i=0;i<=n;i++){ const a=Math.PI*(1.12+i*.76/n), x=(60+46*Math.cos(a)).toFixed(1), y=(75+46*Math.sin(a)).toFixed(1), deg=(a*180/Math.PI+90+(i%2?25:-25)).toFixed(0);
    s += `<ellipse cx="${x}" cy="${y}" rx="7" ry="3" transform="rotate(${deg} ${x} ${y})" fill="${leaf}" stroke="${SK}" stroke-width=".8"/>`; }
  for (let i=0;i<cols.length;i++){ const a=Math.PI*(1.16+i*.68/(cols.length-1)), x=(60+46*Math.cos(a)).toFixed(1), y=(75+46*Math.sin(a)).toFixed(1), r=big?6:4.5;
    s += `<circle cx="${x}" cy="${y}" r="${r}" fill="${cols[i]}" stroke="${SK}" stroke-width="1"/><circle cx="${x}" cy="${y}" r="${r*.35}" fill="#facc15"/>`; }
  return s;
}
